/* Counter hidden selection and real payment-source/review interactions. */
const {chromium}=require('playwright');const {expect}=require('playwright/test');const assert=require('node:assert/strict');const fs=require('node:fs');const path=require('node:path');
const port=Number(process.env.DEEP_AUDIT_PORT||4495);const sizes=process.env.DEEP_AUDIT_SMOKE?[[390,844]]:[[320,700],[360,800],[390,844],[430,932],[768,1024],[1024,768],[1280,800],[1440,900]],languages=process.env.DEEP_AUDIT_SMOKE?['English + Bangla']:['English','English + Bangla','Bangla'];const output=process.env.DEEP_AUDIT_OUTPUT||'.superpowers/deep-audit/counter-actions',results=[];
async function main(){const {createServer}=await import('vite');const s=await createServer({cacheDir:'.superpowers/counter-actions-cache',server:{host:'127.0.0.1',port,strictPort:true}});await s.listen();const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});fs.mkdirSync(output,{recursive:true});try{for(const [width,height]of sizes)for(const theme of ['light','dark'])for(const language of languages){const id=[width,theme,language.replaceAll(' ','')].join('-'),context=await browser.newContext({viewport:{width,height},hasTouch:width<=1024,reducedMotion:'reduce',colorScheme:theme});await context.addInitScript(({theme,language})=>{localStorage.setItem('hisabiq-theme',theme);localStorage.setItem('hisabiq-erp-personal-v1',JSON.stringify({mode:'Simple',language,density:'Compact',terminology:'simple',dateView:'transaction'}));},{theme,language});await context.tracing.start({screenshots:true,snapshots:true,sources:true});const p=await context.newPage();p.setDefaultTimeout(15000);p.setDefaultNavigationTimeout(60000);await p.route('https://fonts.googleapis.com/**',r=>r.abort());const errors=[];p.on('pageerror',e=>errors.push(e.message));const w=(en,bn)=>language==='Bangla'?bn:en,act=e=>width<=1024?e.tap():e.click(),button=(r,en,bn)=>r.getByRole('button',{name:w(en,bn),exact:true});const search=()=>p.getByRole('textbox',{name:w('Search customer','ক্রেতা খুঁজুন'),exact:true}),list=()=>p.getByRole('listbox',{name:w('Matching parties','মিলে যাওয়া নাম'),exact:true});const go=()=>p.goto('http://127.0.0.1:'+port+'/?case='+results.length+'#/app/counter',{waitUntil:'domcontentloaded'});const selectCustomer=async()=>{await search().fill('Rahman');await expect(list()).toBeVisible();await act(p.getByRole('option',{name:/Rahman Hardware/}));};const snapshot=()=>p.evaluate(async()=>{const {getPartyPreviewSnapshot}=await import('/src/data/partyPreviewStore.ts');return getPartyPreviewSnapshot().sources.filter(s=>s.id.startsWith('party-payment:counter-'));});const choose=async(trigger,name)=>{await act(trigger);await expect(p.getByRole('listbox')).toBeVisible();await act(p.getByRole('option',{name,exact:true}));};const check=async(name,run,reset=true)=>{try{if(reset)await go();await run();assert.deepEqual(errors,[]);results.push({id,name,status:'passed'});}catch(e){results.push({id,name,status:'failed',error:e.message});console.error(id,name,e.message);await p.screenshot({path:path.join(output,id+'-'+name+'.png'),fullPage:true});}};
if(!process.env.DEEP_AUDIT_NEW_FIXES_ONLY)await check('escape-enter',async()=>{await search().fill('Rahman');await expect(list()).toBeVisible();await search().press('Escape');await expect(list()).toBeHidden();await search().press('Enter');await expect(p.getByText(w('Selected customer','বাছা ক্রেতা'),{exact:true})).toHaveCount(0);await expect(search()).toHaveValue('Rahman');});
if(!process.env.DEEP_AUDIT_NEW_FIXES_ONLY)await check('pointer-reopen-and-tab-dismiss',async()=>{await search().fill('Rahman');await expect(list()).toBeVisible();await search().press('Escape');await expect(list()).toBeHidden();await act(search());await expect(list()).toBeVisible();await search().press('Tab');await expect(button(p,'Clear Search customer','Clear ক্রেতা খুঁজুন')).toBeFocused();await p.keyboard.press('Tab');await expect(p.getByRole('option').first()).toBeFocused();await p.keyboard.press('Escape');await expect(list()).toBeHidden();await expect(search()).toBeFocused();await act(search());await expect(list()).toBeVisible();const optionCount=await p.getByRole('option').count();await search().press('Tab');for(let i=0;i<=optionCount;i++)await p.keyboard.press('Tab');await expect(list()).toBeHidden();});
await check('selected-invoice-zero-payment-hides-zero-allocation',async()=>{await selectCustomer();await act(p.getByRole('combobox',{name:w('Invoice allocation','বিল বাছুন'),exact:true}));await expect(p.getByRole('listbox')).toBeVisible();await act(p.getByRole('option',{name:/INV-000198/}));await expect(p.getByText(w('Payment allocation preview','কোন বিলে কত টাকা যাবে'),{exact:true})).toHaveCount(0);});
await check('counter-expense-creates-one-visible-preview-record',async()=>{await act(p.getByRole('button',{name:new RegExp('^'+w('Expense','খরচ'))}));const before=await p.evaluate(async()=>{const {getExpensePreviewSnapshot}=await import('/src/data/expensePreviewStore.ts');return getExpensePreviewSnapshot().expenses.length;});await p.getByPlaceholder(w('e.g. Transport','যেমন: পরিবহন')).fill('Counter audit');await p.getByRole('textbox',{name:w('Payment source amount','পেমেন্টের টাকা'),exact:true}).fill('12.50');await p.getByRole('textbox',{name:w('Reference / note (optional)','রেফারেন্স / মন্তব্য (ঐচ্ছিক)'),exact:true}).fill('counter expense browser regression');await act(button(p,'Review record expense','যাচাই করুন: খরচ লিখুন'));const d=p.getByRole('dialog');await expect(d).toBeVisible();if([390,1440].includes(width)){await p.addScriptTag({path:require.resolve('axe-core/axe.min.js')});const violations=await p.evaluate(async()=>{const r=await axe.run(document.querySelector('[data-dialog-root]'),{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa']}});return r.violations.map(v=>({id:v.id,nodes:v.nodes.map(n=>n.target)}));});assert.deepEqual(violations,[],'Counter expense review axe');}await act(button(d,'Confirm & record','নিশ্চিত করে লিখুন'));await expect(d).toBeHidden();const expense=await p.evaluate(async()=>{const {getExpensePreviewSnapshot}=await import('/src/data/expensePreviewStore.ts');return getExpensePreviewSnapshot().expenses.find(e=>e.note==='counter expense browser regression')??null;});assert.ok(expense,'Counter expense must be persisted into the expense preview store');assert.equal(expense.category,'Counter audit');assert.equal(expense.amount,12.5);assert.equal(expense.paid,12.5);assert.equal(expense.payments?.length,1);assert.equal(await p.evaluate(async()=>{const {getExpensePreviewSnapshot}=await import('/src/data/expensePreviewStore.ts');return getExpensePreviewSnapshot().expenses.length;}),before+1);if(width<1024)await act(button(p,'Open ERP navigation','ERP মেনু খুলুন'));await p.locator('a[href="#/app/expenses"]:visible').last().click();await expect(p.getByText('counter expense browser regression',{exact:true})).toBeVisible();},false);
if(!process.env.DEEP_AUDIT_NEW_FIXES_ONLY)await check('split-validation-review-edit-record',async()=>{await selectCustomer();const amounts=p.getByRole('textbox',{name:w('Payment source amount','পেমেন্টের টাকা'),exact:true});await amounts.fill('100');await act(button(p,'Add payment','আরও মাধ্যম'));await amounts.nth(1).fill('0');await act(button(p,'Review receive payment','যাচাই করুন: ক্রেতার টাকা নিন'));await expect(p.getByRole('alert')).toBeVisible();await expect(p.getByRole('dialog')).toHaveCount(0);await choose(p.getByRole('combobox',{name:w('Payment method','টাকার মাধ্যম'),exact:true}).nth(1),w('Bank','ব্যাংক'));await choose(p.getByRole('combobox',{name:w('Payment account','টাকার হিসাব'),exact:true}).nth(1),'BRAC Bank · 7714');await amounts.nth(1).fill('50.25');await p.getByRole('textbox',{name:w('Settlement discount amount','ছাড় বা সমন্বয়ের টাকা'),exact:true}).fill('25');await p.getByRole('textbox',{name:w('Settlement reason','সমন্বয়ের কারণ'),exact:true}).fill('QA settlement');const review=button(p,'Review receive payment','যাচাই করুন: ক্রেতার টাকা নিন');await act(review);const d=p.getByRole('dialog');await expect(d).toContainText('150.25');await expect(d).toContainText('BRAC Bank');await act(button(d,'Edit details','সংশোধন করুন'));await expect(amounts.nth(0)).toHaveValue('100');await expect(amounts.nth(1)).toHaveValue('50.25');await expect(p.getByRole('textbox',{name:w('Settlement reason','সমন্বয়ের কারণ'),exact:true})).toHaveValue('QA settlement');assert.equal((await snapshot()).length,0);await act(review);if([390,1440].includes(width)){await p.addScriptTag({path:require.resolve('axe-core/axe.min.js')});const violations=await p.evaluate(async()=>{const r=await axe.run(document.querySelector('[data-dialog-root]'),{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa']}});return r.violations.map(v=>({id:v.id,nodes:v.nodes.map(n=>n.target)}));});assert.deepEqual(violations,[],'Counter review axe');}await act(button(d,'Confirm & record','নিশ্চিত করে লিখুন'));await expect(d).toBeHidden();const records=await snapshot();assert.equal(records.length,1);assert.equal(records[0].partyId,'c1');assert.equal(records[0].amountPaid,150.25);assert.equal(records[0].discount,25);assert.deepEqual(records[0].paymentSplits.map(s=>[s.accountId,s.amount]),[['acc-cash',100],['acc-brac',50.25]]);await expect(amounts).toHaveCount(1);await expect(amounts).toHaveValue('');await expect(button(p,'Remove payment','পেমেন্টের মাধ্যম সরান')).toBeDisabled();});
await context.tracing.stop(results.some(r=>r.id===id&&r.status==='failed')?{path:path.join(output,id+'.zip')}:{});await context.close();console.log(id,results.filter(r=>r.id===id).map(r=>r.name+':'+r.status).join(','));}}finally{fs.writeFileSync(path.join(output,'results.json'),JSON.stringify(results,null,2));await browser.close();await s.close();}console.log(results.length+' journeys; '+results.filter(r=>r.status==='failed').length+' failed');assert.equal(results.filter(r=>r.status==='failed').length,0);}
main().catch(e=>{console.error(e);process.exitCode=1;});
